class SQLQueryBuilder:

    @staticmethod
    def select(table, columns='*', where=None):
        if not isinstance(columns, str):
            columns_str = ', '.join(columns)
        else:
            columns_str = columns

        sql = f"SELECT {columns_str} FROM {table}"

        if where:
            conditions = []
            for key, value in where.items():
                conditions.append(f"{key}='{value}'")
            sql += f" WHERE {' AND '.join(conditions)}"

        return sql

    @staticmethod
    def insert(table, data):
        columns = ', '.join(data.keys())
        # Escape single quotes by doubling them to prevent SQL injection
        escaped_values = [value.replace("'", "''") for value in data.values()]
        values_str = ', '.join(f"'{value}'" for value in escaped_values)
        sql = f"INSERT INTO {table} ({columns}) VALUES ({values_str})"
        return sql

    @staticmethod
    def delete(table, where=None):
        sql = f"DELETE FROM {table}"

        if where:
            conditions = []
            for key, value in where.items():
                conditions.append(f"{key}='{value}'")
            sql += f" WHERE {' AND '.join(conditions)}"

        return sql

    @staticmethod
    def update(table, data, where=None):
        # Build the SET clause from data dictionary
        set_clauses = []
        for key, value in data.items():
            value_str = str(value)
            escaped_value = value_str.replace("'", "''")
            set_clauses.append(f"{key}='{escaped_value}'")

        sql = f"UPDATE {table} SET {', '.join(set_clauses)}"

        if where:
            conditions = []
            for key, value in where.items():
                value_str = str(value)
                escaped_value = value_str.replace("'", "''")
                conditions.append(f"{key}='{escaped_value}'")
            sql += f" WHERE {' AND '.join(conditions)}"

        return sql
